#!/usr/bin/env node
/* eslint-disable -- generated file (pipeline/crowd/build_worker.mjs) */
/**
 * rare-atlas-worker.mjs: research rare diseases for Phenotech (a rare-disease atlas) with YOUR OpenAI access.
 * Single file, no dependencies, Node >= 20. Run: node rare-atlas-worker.mjs --help
 *
 * What it does: claims a disease from the atlas research queue, sends the PubMed abstracts the atlas
 * fetched to your OpenAI model (your ChatGPT Plus/Pro plan via Sign in with ChatGPT, or OPENAI_API_KEY),
 * submits the extracted claims (the atlas verifies every quote), hands the disease back, repeats.
 * Talks only to the --server you give, auth.openai.com and api.openai.com. Your ChatGPT tokens stay on
 * this machine (~/.rare-atlas-worker/secrets, mode 600) and are never sent to the atlas.
 *
 * Generated by pipeline/crowd/build_worker.mjs from integrations/openai/siwc.mjs, integrations/openai/llm.mjs
 * and pipeline/crowd/worker_main.mjs. Do not edit by hand.
 */
import { createServer } from 'node:http';
import { spawn } from 'node:child_process';
import { createHash, createPublicKey, randomBytes, randomUUID, timingSafeEqual, verify as verifySignature } from 'node:crypto';
import { chmod, mkdir, open, readFile, rename, rm, stat, writeFile } from 'node:fs/promises';
import { readFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import readline from 'node:readline';
import { setTimeout as sleep } from 'node:timers/promises';

const WORKER_HOME = path.resolve(process.env.RARE_ATLAS_HOME || path.join(os.homedir(), '.rare-atlas-worker'));

// ===========================================================================
// Sign in with ChatGPT (copied from integrations/openai/siwc.mjs)
// ===========================================================================
/**
 * Sign in with ChatGPT (SIWC): the open-source / local-app "ChatGPT plan usage" flow.
 * Dependency-free Node ESM (Node >= 20: global fetch, node:crypto JWK import).
 *
 * Implements, as documented on 2026-10-03:
 *   https://developers.openai.com/siwc/token-sharing-open-source/sign-in
 *   https://developers.openai.com/siwc/token-sharing-open-source/profiles-and-sessions
 *   https://developers.openai.com/siwc/token-sharing-open-source/token-reference
 *   https://developers.openai.com/siwc/token-sharing-open-source/errors-and-recovery
 * Written from the docs; no code copied from OpenAI's devkit (it has a noncommercial licence).
 *
 * Public API (none of these ever return or log a token, except getAccessToken):
 *   beginLogin(opts)       start a loopback listener, return { authorizeUrl, redirectUri, completion, cancel }
 *   login(opts)            beginLogin + open the system browser + wait for completion
 *   getAccessToken()       access token for the active account, refreshed automatically near expiry
 *   refresh()              force a refresh_token grant now
 *   logout(opts)           revoke the refresh token remotely, then clear local tokens
 *   status()               read-only summary; never writes files, never makes network calls
 *   previewAuthorizeUrl()  dry run: the URL login() would open; no listener, no files written
 */

// ---------------------------------------------------------------------------
// Constants (values from the SIWC docs)
// ---------------------------------------------------------------------------

const ISSUER = 'https://auth.openai.com';
const RESOURCE = 'https://api.openai.com/v1';
const PLAN_USAGE_SCOPE = 'chatgpt.tokens.use.direct';
const SCOPES = `openid profile email offline_access resource.invoke ${PLAN_USAGE_SCOPE}`;
const DYNAMIC_CLIENT_ID = 'dynamic_agent_client';
/** Path is fixed for the life of a registration ("/callback does not match /auth/callback"); only the port may vary. */
const CALLBACK_PATH = '/auth/callback';
const DEFAULT_CALLBACK_PORT = 1455;
const MANAGE_USAGE_URL = 'https://chatgpt.com/settings/usage';
/**
 * Sent as agent_name_hint on first registration only. The docs ask for the app's actual name, used
 * consistently across installations. The user can edit it on the consent screen.
 */
const APP_NAME = 'Phenotech';

const DOCUMENTED_ENDPOINTS = Object.freeze({
  authorization_endpoint: `${ISSUER}/api/accounts/authorize`,
  token_endpoint: `${ISSUER}/api/accounts/oauth/token`,
  revocation_endpoint: `${ISSUER}/api/accounts/oauth/revoke`,
  jwks_uri: `${ISSUER}/.well-known/jwks.json`,
});

const REFRESH_MARGIN_MS = 60_000;
const LOGIN_TIMEOUT_MS = 10 * 60_000;
const CLOCK_SKEW_S = 30;
const TERMINAL_REFRESH_ERRORS = new Set([
  'invalid_grant',
  'invalid_refresh_token',
  'token_expired',
  'refresh_token_expired',
  'refresh_token_invalidated',
  'refresh_token_reused',
]);
const CLI = 'node rare-atlas-worker.mjs';

// ---------------------------------------------------------------------------
// Paths: <project root>/.secrets/openai-siwc.json (dir 700, file 600)
// ---------------------------------------------------------------------------

const PROJECT_ROOT = WORKER_HOME;
const SECRETS_DIR = process.env.RARE_ATLAS_SECRETS_DIR ? path.resolve(process.env.RARE_ATLAS_SECRETS_DIR) : path.join(WORKER_HOME, 'secrets');
const STORE_PATH = path.join(SECRETS_DIR, 'openai-siwc.json');
const LOCK_PATH = `${STORE_PATH}.lock`;

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

class SiwcError extends Error {
  constructor(code, message, { status, retryable = false, requestId, cause } = {}) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = 'SiwcError';
    this.code = code;
    this.retryable = retryable;
    if (status !== undefined) this.status = status;
    if (requestId) this.requestId = requestId;
  }
}

/** No usable ChatGPT session: never signed in, signed out, or the refresh token is no longer valid. */
class LoginRequiredError extends SiwcError {
  constructor(message = `Not signed in with ChatGPT. Run: ${CLI} login`, options) {
    super('login_required', message, options);
    this.name = 'LoginRequiredError';
  }
}

/** Signed in, but the user did not grant chatgpt.tokens.use.direct. Do not attempt inference with it. */
class PlanUsageNotGrantedError extends SiwcError {
  constructor(message = `ChatGPT plan usage was not granted. Run: ${CLI} login --reconsent`, options) {
    super('plan_usage_not_granted', message, options);
    this.name = 'PlanUsageNotGrantedError';
  }
}

/** The user cancelled or declined in the browser (error=access_denied). */
class ConsentDeclinedError extends SiwcError {
  constructor(message = 'Sign-in was cancelled or declined in the browser (access_denied). Nothing was granted.', options) {
    super('access_denied', message, options);
    this.name = 'ConsentDeclinedError';
  }
}

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const randomValue = (bytes = 32) => randomBytes(bytes).toString('base64url');
const nowIso = () => new Date().toISOString();
const safeCode = (value) =>
  typeof value === 'string' && /^[A-Za-z0-9_.:-]{1,100}$/.test(value) ? value : undefined;

function safeEqual(a, b) {
  const left = Buffer.from(String(a));
  const right = Buffer.from(String(b));
  return left.length === right.length && timingSafeEqual(left, right);
}

function parseScopes(value) {
  if (Array.isArray(value)) return value.filter((scope) => typeof scope === 'string' && scope);
  return typeof value === 'string' ? value.split(/\s+/).filter(Boolean) : [];
}

/** PKCE (RFC 7636): 32 random bytes -> 43-char verifier; S256 challenge, base64url without padding. */
function pkcePair() {
  const verifier = randomValue(32);
  const challenge = createHash('sha256').update(verifier).digest('base64url');
  return { verifier, challenge };
}

async function fetchWithTimeout(url, init = {}, timeoutMs = 30_000) {
  const timeout = AbortSignal.timeout(timeoutMs);
  const signal = init.signal ? AbortSignal.any([init.signal, timeout]) : timeout;
  try {
    return await fetch(url, { ...init, signal, redirect: 'error' });
  } catch (error) {
    const reason = error?.cause?.code ?? error?.name ?? 'network error';
    throw new SiwcError('network_error', `Could not reach ${new URL(url).host} (${reason}).`, {
      retryable: true,
      cause: error,
    });
  }
}

async function readJson(response) {
  try {
    return await response.json();
  } catch {
    return undefined;
  }
}

// ---------------------------------------------------------------------------
// OIDC discovery (verified against the documented production values)
// ---------------------------------------------------------------------------

let endpointsPromise;

/** Endpoints from https://auth.openai.com/.well-known/openid-configuration, falling back to documented values. */
function endpoints() {
  endpointsPromise ??= (async () => {
    const result = { ...DOCUMENTED_ENDPOINTS };
    try {
      const response = await fetchWithTimeout(`${ISSUER}/.well-known/openid-configuration`, {
        headers: { accept: 'application/json' },
      }, 15_000);
      const doc = await readJson(response);
      if (!response.ok || !isObject(doc) || doc.issuer !== ISSUER) return result;
      for (const key of Object.keys(DOCUMENTED_ENDPOINTS)) {
        // Only accept endpoints on the issuer's own origin.
        if (typeof doc[key] === 'string' && new URL(doc[key]).origin === ISSUER) result[key] = doc[key];
      }
    } catch {
      // Network trouble: the documented production endpoints are used.
    }
    return result;
  })();
  return endpointsPromise;
}

// ---------------------------------------------------------------------------
// Credential store (single JSON file, atomic writes, owner-only permissions)
//
// {
//   "version": 1,
//   "ext_agent_host_id": "urn:uuid:...",          stable per install; not a credential
//   "active_client_id": "oaiapp_...",
//   "accounts": { "<issued client_id>": <record> } record = documented fields + expires_at
// }
// ---------------------------------------------------------------------------

function emptyStore(hostId) {
  return { version: 1, ext_agent_host_id: hostId, active_client_id: null, accounts: {} };
}

async function readStore() {
  let raw;
  try {
    raw = await readFile(STORE_PATH, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw new SiwcError('store_unreadable', `Could not read ${STORE_PATH} (${error.code}).`);
  }
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new SiwcError('store_corrupt', `${STORE_PATH} is not valid JSON. Delete it and sign in again.`);
  }
  if (!isObject(data) || typeof data.ext_agent_host_id !== 'string') {
    throw new SiwcError('store_corrupt', `${STORE_PATH} has an unexpected format. Delete it and sign in again.`);
  }
  if (!isObject(data.accounts)) data.accounts = {};
  return data;
}

async function ensureSecretsDir() {
  await mkdir(SECRETS_DIR, { recursive: true, mode: 0o700 });
  await chmod(SECRETS_DIR, 0o700); // mkdir's mode is ignored for an existing dir and masked by umask
}

async function writeStore(data) {
  await ensureSecretsDir();
  const temporary = `${STORE_PATH}.${process.pid}.${randomValue(6)}.tmp`;
  const handle = await open(temporary, 'wx', 0o600);
  try {
    await handle.writeFile(`${JSON.stringify(data, null, 2)}\n`, 'utf8');
    await handle.sync();
  } finally {
    await handle.close();
  }
  try {
    await chmod(temporary, 0o600);
    await rename(temporary, STORE_PATH);
  } catch (error) {
    await rm(temporary, { force: true });
    throw error;
  }
}

// Refresh tokens rotate, so refreshes must be serialized within this process and across processes
// (for example the CLI and the Next.js dev server). In-process queue + O_EXCL lock file.
let localQueue = Promise.resolve();

function withStoreLock(fn) {
  const run = localQueue.then(() => withFileLock(fn));
  localQueue = run.catch(() => {});
  return run;
}

async function withFileLock(fn, { waitMs = 20_000, staleMs = 90_000 } = {}) {
  await ensureSecretsDir();
  const started = Date.now();
  for (;;) {
    try {
      const handle = await open(LOCK_PATH, 'wx', 0o600);
      await handle.writeFile(`${process.pid}\n`);
      await handle.close();
      break;
    } catch (error) {
      if (error.code !== 'EEXIST') throw error;
      const info = await stat(LOCK_PATH).catch(() => null);
      if (info && Date.now() - info.mtimeMs > staleMs) {
        await rm(LOCK_PATH, { force: true });
        continue;
      }
      if (Date.now() - started > waitMs) {
        throw new SiwcError('store_busy', 'Another process is updating the ChatGPT credentials. Try again shortly.', {
          retryable: true,
        });
      }
      await sleep(50 + Math.floor(Math.random() * 100));
    }
  }
  try {
    return await fn();
  } finally {
    await rm(LOCK_PATH, { force: true });
  }
}

async function ensureHostId() {
  const existing = await readStore();
  if (existing?.ext_agent_host_id) return existing.ext_agent_host_id;
  return withStoreLock(async () => {
    const current = await readStore();
    if (current?.ext_agent_host_id) return current.ext_agent_host_id;
    // Docs: choose and persist the host ID before the first sign-in. UUIDv4 as a urn:uuid: URI.
    const store = emptyStore(`urn:uuid:${randomUUID()}`);
    await writeStore(store);
    return store.ext_agent_host_id;
  });
}

function activeAccount(store) {
  if (!store?.active_client_id) return null;
  const account = store.accounts?.[store.active_client_id];
  return isObject(account) ? account : null;
}

const hasPlanUsage = (account) => parseScopes(account?.scopes).includes(PLAN_USAGE_SCOPE);

function expiresAtMs(account) {
  const time = Date.parse(account?.expires_at ?? '');
  return Number.isFinite(time) ? time : 0;
}

/** earliest_refresh_at's type is undocumented: accept Unix seconds, Unix ms or an ISO string. */
function earliestRefreshMs(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value > 1e12 ? value : value * 1000;
  if (typeof value === 'string' && value.trim()) {
    const number = Number(value);
    if (Number.isFinite(number)) return earliestRefreshMs(number);
    const time = Date.parse(value);
    return Number.isFinite(time) ? time : 0;
  }
  return 0;
}

/** Drop tokens but keep the registration (client_id, subject, email) and host ID for a later sign-in. */
function withoutTokens(account, status) {
  const {
    access_token: _access,
    refresh_token: _refresh,
    id_token: _id,
    token_type: _type,
    expires_in: _expiresIn,
    expires_at: _expiresAt,
    earliest_refresh_at: _earliest,
    ...rest
  } = account;
  return { ...rest, scopes: [], status, saved_at: nowIso() };
}

// ---------------------------------------------------------------------------
// Token endpoint + ID token verification (RS256 against OpenAI's JWKS, no dependencies)
// ---------------------------------------------------------------------------

function oauthErrorCode(body) {
  if (!isObject(body)) return undefined;
  if (typeof body.error === 'string') return safeCode(body.error);
  if (isObject(body.error)) return safeCode(body.error.code) ?? safeCode(body.error.type);
  return safeCode(body.code);
}

async function tokenRequest(params) {
  const { token_endpoint: tokenEndpoint } = await endpoints();
  const response = await fetchWithTimeout(tokenEndpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded', accept: 'application/json' },
    body: new URLSearchParams(params),
  });
  const requestId = response.headers.get('x-request-id') ?? response.headers.get('openai-request-id') ?? undefined;
  const data = await readJson(response);
  if (!response.ok) {
    const code = oauthErrorCode(data) ?? `http_${response.status}`;
    throw new SiwcError(code, `The OpenAI token endpoint returned HTTP ${response.status} (${code}).`, {
      status: response.status,
      retryable: response.status >= 500,
      requestId,
    });
  }
  if (!isObject(data)) {
    throw new SiwcError('invalid_token_response', 'The OpenAI token endpoint returned an unexpected body.', { requestId });
  }
  return data;
}

function credentialFields(data, { requireRefresh }) {
  const invalid = (what) => new SiwcError('invalid_token_response', `The token response ${what}. Sign in again.`);
  if (typeof data.access_token !== 'string' || !data.access_token) throw invalid('did not include an access token');
  if (typeof data.token_type !== 'string' || data.token_type.toLowerCase() !== 'bearer') throw invalid('had an unexpected token_type');
  const expiresIn = Number(data.expires_in);
  if (!Number.isFinite(expiresIn) || expiresIn <= 0) throw invalid('had no valid expires_in');
  const hasRefresh = typeof data.refresh_token === 'string' && data.refresh_token.length > 0;
  if (requireRefresh && !hasRefresh) throw invalid('did not include a refresh token although offline_access was granted');
  const receivedAt = Date.now();
  return {
    access_token: data.access_token,
    ...(hasRefresh ? { refresh_token: data.refresh_token } : {}),
    token_type: 'Bearer',
    expires_in: expiresIn,
    expires_at: new Date(receivedAt + expiresIn * 1000).toISOString(),
    ...(data.earliest_refresh_at !== undefined && data.earliest_refresh_at !== null
      ? { earliest_refresh_at: data.earliest_refresh_at }
      : {}),
    saved_at: new Date(receivedAt).toISOString(),
  };
}

let jwksCache = { uri: '', keys: [], fetchedAt: 0 };

async function signingKeys({ force = false } = {}) {
  const { jwks_uri: jwksUri } = await endpoints();
  const fresh = Date.now() - jwksCache.fetchedAt < 60 * 60_000;
  if (!force && jwksCache.uri === jwksUri && jwksCache.keys.length && fresh) return jwksCache.keys;
  let response;
  try {
    response = await fetchWithTimeout(jwksUri, { headers: { accept: 'application/json' } }, 15_000);
  } catch (error) {
    throw new SiwcError('jwks_unavailable', 'Could not download OpenAI signing keys to verify the ID token.', {
      retryable: true,
      cause: error,
    });
  }
  const body = await readJson(response);
  if (!response.ok || !isObject(body) || !Array.isArray(body.keys)) {
    throw new SiwcError('jwks_unavailable', 'OpenAI signing keys were unavailable. Try again shortly.', { retryable: true });
  }
  jwksCache = { uri: jwksUri, keys: body.keys.filter(isObject), fetchedAt: Date.now() };
  return jwksCache.keys;
}

const decodeSegment = (segment) => JSON.parse(Buffer.from(segment, 'base64url').toString('utf8'));

/** Verify signature (RS256 via JWKS), iss, aud/azp, exp, iat and (when given) nonce. Returns the claims. */
async function verifyIdToken(idToken, { clientId, nonce } = {}) {
  const invalid = (why) => new SiwcError('invalid_id_token', `The ChatGPT ID token failed verification (${why}).`);
  if (typeof idToken !== 'string' || !idToken) throw invalid('missing');
  const parts = idToken.split('.');
  if (parts.length !== 3) throw invalid('format');
  let header;
  let payload;
  try {
    header = decodeSegment(parts[0]);
    payload = decodeSegment(parts[1]);
  } catch {
    throw invalid('encoding');
  }
  if (!isObject(header) || !isObject(payload) || header.alg !== 'RS256') throw invalid('algorithm');

  const pick = (keys) =>
    keys.find(
      (key) =>
        key.kid === header.kid && key.kty === 'RSA' && (!key.use || key.use === 'sig') && (!key.alg || key.alg === 'RS256'),
    );
  let jwk = pick(await signingKeys());
  if (!jwk) jwk = pick(await signingKeys({ force: true })); // unfamiliar kid: refresh keys once
  if (!jwk) throw invalid('unknown signing key');

  let signatureOk = false;
  try {
    const key = createPublicKey({ key: { kty: 'RSA', n: jwk.n, e: jwk.e }, format: 'jwk' });
    signatureOk = verifySignature(
      'RSA-SHA256',
      Buffer.from(`${parts[0]}.${parts[1]}`),
      key,
      Buffer.from(parts[2], 'base64url'),
    );
  } catch {
    signatureOk = false;
  }
  if (!signatureOk) throw invalid('signature');

  const now = Math.floor(Date.now() / 1000);
  const audiences = Array.isArray(payload.aud) ? payload.aud : [payload.aud];
  if (payload.iss !== ISSUER) throw invalid('issuer');
  if (!clientId || !audiences.includes(clientId)) throw invalid('audience');
  if (payload.azp !== undefined && payload.azp !== clientId) throw invalid('authorized party');
  if (audiences.length > 1 && payload.azp !== clientId) throw invalid('authorized party');
  if (typeof payload.exp !== 'number' || payload.exp + CLOCK_SKEW_S < now) throw invalid('expired');
  if (typeof payload.iat !== 'number' || payload.iat - CLOCK_SKEW_S > now) throw invalid('issued in the future');
  if (nonce !== undefined && payload.nonce !== nonce) throw invalid('nonce');
  if (typeof payload.sub !== 'string' || !payload.sub) throw invalid('subject');
  return payload;
}

// ---------------------------------------------------------------------------
// Authorization URL + loopback callback listener
// ---------------------------------------------------------------------------

/** Build the authorize URL exactly as the sign-in guide's parameter table describes. */
function buildAuthorizeUrl({
  authorizationEndpoint = DOCUMENTED_ENDPOINTS.authorization_endpoint,
  clientId = DYNAMIC_CLIENT_ID,
  redirectUri,
  state,
  nonce,
  codeChallenge,
  hostId,
  agentNameHint = APP_NAME,
  loginHint,
  reconsent = false,
}) {
  if (!redirectUri || !state || !nonce || !codeChallenge || !hostId) {
    throw new TypeError('buildAuthorizeUrl: redirectUri, state, nonce, codeChallenge and hostId are required.');
  }
  const params = new URLSearchParams({
    client_id: clientId,
    response_type: 'code',
    redirect_uri: redirectUri,
    scope: SCOPES,
    resource: RESOURCE,
    state,
    nonce,
    code_challenge_method: 'S256',
    code_challenge: codeChallenge,
    ext_agent_host_id: hostId,
  });
  // agent_name_hint only on initial dynamic registration; omit it when reauthorizing an issued client.
  if (clientId === DYNAMIC_CLIENT_ID) params.set('agent_name_hint', agentNameHint);
  // login_hint (saved email) only for reauthorization. id_token_hint is deliberately not sent: it is
  // optional, and the URL is passed to `open` as a process argument, which other local users can read.
  if (loginHint && clientId !== DYNAMIC_CLIENT_ID) params.set('login_hint', loginHint);
  // Re-request consent after an earlier decline (docs: prompt=consent until force_reconsent is confirmed).
  if (reconsent) params.set('prompt', 'consent');
  const url = new URL(authorizationEndpoint);
  url.search = params.toString();
  return url.toString();
}

const PAGE_SCRIPT = 'history.replaceState(null, "", "/auth/complete");';
const PAGE_SCRIPT_HASH = createHash('sha256').update(PAGE_SCRIPT).digest('base64');

function sendPage(response, status, title, body) {
  // title/body are constants from this file; no request data is reflected into the page.
  response.writeHead(status, {
    'content-type': 'text/html; charset=utf-8',
    'cache-control': 'no-store',
    'referrer-policy': 'no-referrer',
    'content-security-policy': `default-src 'none'; script-src 'sha256-${PAGE_SCRIPT_HASH}'; style-src 'unsafe-inline'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'`,
  });
  response.end(
    `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${title}</title>` +
      '<style>body{font:16px/1.5 system-ui,sans-serif;max-width:34rem;margin:15vh auto;padding:0 20px;color:#1f2328}h1{font-size:22px}</style></head>' +
      `<body><h1>${title}</h1><p>${body}</p><script>${PAGE_SCRIPT}</script></body></html>`,
  );
}

async function startCallbackListener({ port, allowPortFallback, state, savedClientId }) {
  let settled = false;
  let settle;
  const result = new Promise((resolve, reject) => {
    settle = (error, value) => (error ? reject(error) : resolve(value));
  });
  result.catch(() => {});
  const finish = (error, value) => {
    if (settled) return;
    settled = true;
    settle(error, value);
  };
  let boundPort = port;

  const server = createServer((request, response) => {
    let url;
    try {
      url = new URL(request.url ?? '/', `http://127.0.0.1:${boundPort}`);
    } catch {
      response.writeHead(400).end();
      return;
    }
    // Exact loopback host (blocks DNS rebinding) and exact callback path.
    if (request.method !== 'GET' || request.headers.host !== `127.0.0.1:${boundPort}` || url.pathname !== CALLBACK_PATH) {
      response.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' }).end('Not found');
      return;
    }
    if (settled) {
      sendPage(response, 410, 'Sign-in already handled', 'This sign-in attempt has finished. You can close this tab.');
      return;
    }
    const states = url.searchParams.getAll('state');
    if (states.length !== 1 || !safeEqual(states[0], state)) {
      // A stale or unrelated request must not consume the pending attempt.
      sendPage(response, 400, 'Sign-in could not be verified', 'This page does not belong to the current sign-in attempt. Return to the tab that started sign-in.');
      return;
    }
    const error = url.searchParams.get('error');
    if (error) {
      if (error === 'access_denied') {
        sendPage(response, 200, 'Sign-in cancelled', 'No access was granted. You can close this tab.');
        finish(new ConsentDeclinedError());
      } else {
        const code = safeCode(error) ?? 'authorization_error';
        sendPage(response, 400, 'Sign-in failed', 'ChatGPT returned an error. Return to the app for details.');
        finish(new SiwcError(code, `Authorization failed (${code}).`));
      }
      return;
    }
    const codes = url.searchParams.getAll('code');
    const returnedIds = url.searchParams.getAll('client_id');
    const returnedClientId = returnedIds[0] ?? null;
    const clientId = returnedClientId ?? savedClientId ?? null;
    const mismatch = Boolean(savedClientId && returnedClientId && returnedClientId !== savedClientId);
    if (
      codes.length !== 1 ||
      !codes[0] ||
      returnedIds.length > 1 ||
      !clientId ||
      clientId === DYNAMIC_CLIENT_ID ||
      !/^[A-Za-z0-9_-]{1,200}$/.test(clientId) ||
      mismatch
    ) {
      sendPage(response, 400, 'Sign-in incomplete', 'ChatGPT did not complete app registration. Return to the app and try again.');
      finish(
        new SiwcError(
          'registration_incomplete',
          mismatch
            ? 'The callback returned a different client ID than the saved registration, so the result was rejected.'
            : 'ChatGPT did not return an authorization code and an issued client ID. Try signing in again.',
        ),
      );
      return;
    }
    sendPage(response, 200, 'Signed in with ChatGPT', 'You can close this tab and return to the app.');
    finish(null, { code: codes[0], clientId, isNewRegistration: !savedClientId });
  });
  server.requestTimeout = 15_000;
  server.headersTimeout = 10_000;

  const listen = (candidate) =>
    new Promise((resolve, reject) => {
      const onError = (error) => {
        server.off('listening', onListening);
        reject(error);
      };
      const onListening = () => {
        server.off('error', onError);
        resolve();
      };
      server.once('error', onError);
      server.once('listening', onListening);
      server.listen({ port: candidate, host: '127.0.0.1', exclusive: true });
    });

  try {
    await listen(port);
  } catch (error) {
    if (!(allowPortFallback && error.code === 'EADDRINUSE')) {
      throw new SiwcError('callback_port_unavailable', `Port ${port} on 127.0.0.1 is unavailable (${error.code}). Pass --port or set SIWC_PORT.`);
    }
    await listen(0); // any free port; the docs allow the port (only) to vary between attempts
  }
  boundPort = server.address().port;
  server.on('error', () => finish(new SiwcError('callback_failed', 'The local sign-in listener stopped. Try again.')));

  return {
    redirectUri: `http://127.0.0.1:${boundPort}${CALLBACK_PATH}`,
    result,
    fail: (error) => finish(error),
    close: () => {
      server.close();
      server.closeAllConnections?.();
    },
  };
}

// ---------------------------------------------------------------------------
// Login
// ---------------------------------------------------------------------------

let pendingLogin = null;

/**
 * Start a sign-in attempt without opening a browser (a web UI can open authorizeUrl itself).
 * Returns { authorizeUrl, redirectUri, completion: Promise<LoginResult>, cancel() }.
 * Only one attempt runs per process; a second call returns the pending one.
 *
 * Options: newAccount (register another ChatGPT account instead of reauthorizing the saved one),
 *          reconsent (prompt=consent, to enable plan usage after an earlier decline), port, timeoutMs.
 */
function beginLogin(options = {}) {
  if (pendingLogin) return pendingLogin;
  pendingLogin = startLogin(options);
  pendingLogin.catch(() => {
    pendingLogin = null;
  });
  return pendingLogin;
}

async function startLogin({ newAccount = false, reconsent = false, port, timeoutMs = LOGIN_TIMEOUT_MS } = {}) {
  const hostId = await ensureHostId();
  const previous = newAccount ? null : activeAccount(await readStore());
  const savedClientId =
    previous?.client_id && previous.client_id !== DYNAMIC_CLIENT_ID ? previous.client_id : undefined;
  const { authorization_endpoint: authorizationEndpoint } = await endpoints();

  // Fresh state, nonce and PKCE verifier for every attempt.
  const state = randomValue();
  const nonce = randomValue();
  const { verifier, challenge } = pkcePair();

  const envPort = process.env.SIWC_PORT !== undefined && process.env.SIWC_PORT !== '' ? Number(process.env.SIWC_PORT) : undefined;
  const explicitPort = port ?? envPort;
  if (explicitPort !== undefined && (!Number.isInteger(explicitPort) || explicitPort < 0 || explicitPort > 65535)) {
    throw new TypeError(`Invalid callback port: ${explicitPort}`);
  }
  const listener = await startCallbackListener({
    port: explicitPort ?? DEFAULT_CALLBACK_PORT,
    allowPortFallback: explicitPort === undefined,
    state,
    savedClientId,
  });

  let authorizeUrl;
  try {
    authorizeUrl = buildAuthorizeUrl({
      authorizationEndpoint,
      clientId: savedClientId ?? DYNAMIC_CLIENT_ID,
      redirectUri: listener.redirectUri,
      state,
      nonce,
      codeChallenge: challenge,
      hostId,
      loginHint: savedClientId ? previous?.email : undefined,
      reconsent,
    });
  } catch (error) {
    listener.close();
    throw error;
  }

  const timer = setTimeout(
    () => listener.fail(new SiwcError('login_timeout', 'Timed out waiting for the browser sign-in to finish.')),
    timeoutMs,
  );

  const completion = (async () => {
    try {
      const callback = await listener.result;

      // Save the issued client ID before the one-time code exchange, so a failed exchange is retried
      // with the same registration instead of registering a new client. It only becomes the active
      // account now if there is no other signed-in account (a new attempt stays separate until verified).
      if (callback.isNewRegistration) {
        await withStoreLock(async () => {
          const store = (await readStore()) ?? emptyStore(hostId);
          const existing = store.accounts[callback.clientId];
          store.accounts[callback.clientId] = {
            ...(isObject(existing) ? existing : { status: 'registered', scopes: [] }),
            client_id: callback.clientId,
            issuer: ISSUER,
            ext_agent_host_id: store.ext_agent_host_id,
            saved_at: nowIso(),
          };
          const active = activeAccount(store);
          if (!active || (!active.access_token && !active.refresh_token)) store.active_client_id = callback.clientId;
          await writeStore(store);
        });
      }

      const tokens = await tokenRequest({
        grant_type: 'authorization_code',
        client_id: callback.clientId,
        code: callback.code,
        code_verifier: verifier,
        redirect_uri: listener.redirectUri,
        resource: RESOURCE,
      });

      if (typeof tokens.id_token !== 'string' || !tokens.id_token) {
        throw new SiwcError('invalid_id_token', 'The token response did not include an ID token.');
      }
      const claims = await verifyIdToken(tokens.id_token, { clientId: callback.clientId, nonce });
      const prior = (await readStore())?.accounts?.[callback.clientId];
      if (isObject(prior) && prior.subject && prior.subject !== claims.sub) {
        throw new SiwcError(
          'account_mismatch',
          `This sign-in returned a different ChatGPT account than the saved one. Use \`${CLI} login --new-account\` to add another account.`,
        );
      }
      // Docs: decide on plan usage from the token response's granted scopes, not the callback.
      if (typeof tokens.scope !== 'string') {
        throw new SiwcError('invalid_token_response', 'The token response did not confirm the granted scopes. Sign in again.');
      }
      const scopes = parseScopes(tokens.scope);
      const hasAccess = typeof tokens.access_token === 'string' && tokens.access_token.length > 0;
      const fields = hasAccess ? credentialFields(tokens, { requireRefresh: scopes.includes('offline_access') }) : {};
      const planUsage = hasAccess && scopes.includes(PLAN_USAGE_SCOPE);
      const firstPlanUsageSignIn = planUsage && !prior?.plan_usage_first_enabled_at;

      const record = {
        email: typeof claims.email === 'string' ? claims.email : (prior?.email ?? null),
        ...(typeof claims.name === 'string' ? { name: claims.name } : {}),
        issuer: ISSUER,
        subject: claims.sub,
        client_id: callback.clientId,
        ext_agent_host_id: hostId,
        id_token: tokens.id_token,
        ...fields,
        scopes,
        status: 'connected',
        plan_usage_first_enabled_at: prior?.plan_usage_first_enabled_at ?? (planUsage ? nowIso() : undefined),
        saved_at: nowIso(),
      };

      await withStoreLock(async () => {
        const store = (await readStore()) ?? emptyStore(hostId);
        store.accounts[callback.clientId] = record;
        store.active_client_id = callback.clientId;
        await writeStore(store);
      });

      return {
        email: record.email,
        name: record.name ?? null,
        clientId: record.client_id,
        newRegistration: callback.isNewRegistration,
        scopes,
        planUsage,
        firstPlanUsageSignIn,
        accessTokenExpiresAt: record.expires_at ?? null,
        manageUsageUrl: MANAGE_USAGE_URL,
      };
    } finally {
      clearTimeout(timer);
      listener.close();
      pendingLogin = null;
    }
  })();
  completion.catch(() => {});

  return {
    authorizeUrl,
    redirectUri: listener.redirectUri,
    completion,
    cancel: () => listener.fail(new SiwcError('cancelled', 'Sign-in was cancelled.')),
  };
}

/** Open a URL in the system browser (macOS `open`; xdg-open / rundll32 elsewhere). */
function openInBrowser(url) {
  const command = process.platform === 'darwin' ? 'open' : process.platform === 'win32' ? 'rundll32' : 'xdg-open';
  const args = process.platform === 'win32' ? ['url.dll,FileProtocolHandler', url] : [url];
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, { stdio: 'ignore', shell: false });
    child.once('error', (error) => reject(new SiwcError('browser_unavailable', `Could not run ${command}: ${error.code ?? error.message}`)));
    child.once('exit', (code) =>
      code === 0 ? resolve() : reject(new SiwcError('browser_unavailable', `${command} exited with code ${code}.`)),
    );
  });
}

/**
 * Full interactive login: listener + browser + wait. Resolves with a LoginResult (no tokens).
 * onAuthorizeUrl(url) is called before the browser opens (print it as a fallback);
 * pass openBrowser: false to only print/return the URL.
 */
async function login({ openBrowser = true, onAuthorizeUrl, onBrowserError, ...options } = {}) {
  const attempt = await beginLogin(options);
  onAuthorizeUrl?.(attempt.authorizeUrl, attempt.redirectUri);
  if (openBrowser) {
    try {
      await openInBrowser(attempt.authorizeUrl);
    } catch (error) {
      if (onBrowserError) onBrowserError(error, attempt.authorizeUrl);
      else {
        attempt.cancel();
        throw error;
      }
    }
  }
  return attempt.completion;
}

// ---------------------------------------------------------------------------
// Tokens: refresh + access
// ---------------------------------------------------------------------------

async function refreshAccount(store, account) {
  let data;
  try {
    data = await tokenRequest({
      grant_type: 'refresh_token',
      client_id: account.client_id, // the issued client ID, never dynamic_agent_client
      refresh_token: account.refresh_token,
      resource: RESOURCE, // scope omitted to retain the grant
    });
  } catch (error) {
    if (error instanceof SiwcError && TERMINAL_REFRESH_ERRORS.has(error.code)) {
      store.accounts[account.client_id] = withoutTokens(account, 'reauth_required');
      await writeStore(store);
      throw new LoginRequiredError(
        `Your ChatGPT session can no longer be renewed (${error.code}). Sign in again: ${CLI} login`,
        { cause: error, status: error.status },
      );
    }
    if (error instanceof SiwcError && error.code === 'invalid_client') {
      throw new SiwcError('invalid_client', `OpenAI rejected the saved client registration (invalid_client). Run: ${CLI} login --new-account`, {
        cause: error,
        status: error.status,
      });
    }
    throw error; // temporary failure: keep credentials (docs: never erase them on a transient error)
  }

  const scopes = typeof data.scope === 'string' ? parseScopes(data.scope) : parseScopes(account.scopes);
  const fields = credentialFields(data, { requireRefresh: false });
  let identity = {};
  if (typeof data.id_token === 'string' && data.id_token) {
    try {
      const claims = await verifyIdToken(data.id_token, { clientId: account.client_id });
      if (account.subject && claims.sub !== account.subject) {
        throw new SiwcError('account_mismatch', 'The refreshed ChatGPT identity does not match the saved account.');
      }
      identity = { id_token: data.id_token, ...(typeof claims.email === 'string' ? { email: claims.email } : {}) };
    } catch (error) {
      if (!(error instanceof SiwcError && error.code === 'jwks_unavailable')) {
        store.accounts[account.client_id] = withoutTokens(account, 'reauth_required');
        await writeStore(store);
        throw new LoginRequiredError(`The refreshed ChatGPT identity could not be verified (${error.code ?? 'error'}). Sign in again: ${CLI} login`, {
          cause: error,
        });
      }
      // Signing keys temporarily unreachable. The old refresh token is already consumed, so keep the
      // new credentials (they came straight from the token endpoint) and keep the previous ID token.
    }
  }

  const { earliest_refresh_at: _previousEarliest, ...base } = account;
  // Replace access token, expiry, scopes and the rotated refresh token together.
  const updated = {
    ...base,
    ...identity,
    ...fields,
    refresh_token: fields.refresh_token ?? account.refresh_token,
    scopes,
    status: 'connected',
  };
  store.accounts[account.client_id] = updated;
  await writeStore(store);
  return updated;
}

const isConnected = (account) =>
  Boolean(account && account.status === 'connected' && (account.access_token || account.refresh_token || account.id_token));

function assertUsable(account) {
  if (!isConnected(account)) {
    throw new LoginRequiredError(
      account?.status === 'reauth_required'
        ? `Your ChatGPT session expired or was revoked. Sign in again: ${CLI} login`
        : undefined,
    );
  }
  if (!hasPlanUsage(account) || (!account.access_token && !account.refresh_token)) {
    throw new PlanUsageNotGrantedError(
      `Signed in${account.email ? ` as ${account.email}` : ''}, but ChatGPT plan usage (${PLAN_USAGE_SCOPE}) was not granted. To enable it: ${CLI} login --reconsent`,
    );
  }
}

/**
 * Access token for the active account with plan usage granted, refreshed when it is within
 * minValidityMs of expiry. Throws LoginRequiredError / PlanUsageNotGrantedError when unusable.
 * Never log or return this token to a browser.
 */
async function getAccessToken({ minValidityMs = REFRESH_MARGIN_MS } = {}) {
  const account = activeAccount(await readStore());
  assertUsable(account);
  if (account.access_token && expiresAtMs(account) - Date.now() > minValidityMs) return account.access_token;

  return withStoreLock(async () => {
    const store = await readStore();
    const current = activeAccount(store);
    assertUsable(current);
    const remaining = expiresAtMs(current) - Date.now();
    if (current.access_token && remaining > minValidityMs) return current.access_token; // refreshed meanwhile
    const earliest = earliestRefreshMs(current.earliest_refresh_at);
    if (current.access_token && remaining > 0 && earliest > Date.now()) return current.access_token;
    if (!current.refresh_token) {
      store.accounts[current.client_id] = withoutTokens(current, 'reauth_required');
      await writeStore(store);
      throw new LoginRequiredError(`Your ChatGPT session expired. Sign in again: ${CLI} login`);
    }
    const updated = await refreshAccount(store, current);
    assertUsable(updated);
    return updated.access_token;
  });
}

/** Force a refresh_token grant for the active account. Resolves with a summary (no tokens). */
async function refresh() {
  if (!activeAccount(await readStore())?.refresh_token) throw new LoginRequiredError();
  return withStoreLock(async () => {
    const store = await readStore();
    const account = activeAccount(store);
    if (!account?.refresh_token) throw new LoginRequiredError();
    const updated = await refreshAccount(store, account);
    return {
      email: updated.email ?? null,
      scopes: parseScopes(updated.scopes),
      planUsage: hasPlanUsage(updated),
      accessTokenExpiresAt: updated.expires_at ?? null,
    };
  });
}

// ---------------------------------------------------------------------------
// Logout
// ---------------------------------------------------------------------------

async function revokeRefreshToken(account) {
  const { revocation_endpoint: revocationEndpoint } = await endpoints();
  let problem = 'unknown error';
  for (let attempt = 0; attempt < 3; attempt += 1) {
    if (attempt) await sleep(400 * attempt);
    try {
      const response = await fetchWithTimeout(revocationEndpoint, {
        method: 'POST',
        headers: { 'content-type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          token: account.refresh_token,
          token_type_hint: 'refresh_token',
          client_id: account.client_id,
        }),
      }, 10_000);
      await response.body?.cancel().catch(() => {});
      if (response.status === 200) return { revoked: true }; // empty 200, also for already-invalid tokens
      problem = `HTTP ${response.status}`;
      if (response.status < 500) break; // only network errors and 5xx are retried
    } catch (error) {
      problem = error.code ?? 'network error';
    }
  }
  return { revoked: false, problem };
}

/**
 * Sign out of the active account: revoke the renewable session, then clear access/refresh/ID tokens.
 * The registration (issued client_id) and this host's ext_agent_host_id are kept for a later sign-in.
 */
async function logout({ revoke = true } = {}) {
  const hasTokens = (account) => Boolean(account && (account.access_token || account.refresh_token || account.id_token));
  const notSignedIn = { signedOut: false, revoked: false, message: 'Not signed in.' };
  if (!hasTokens(activeAccount(await readStore()))) return notSignedIn;
  return withStoreLock(async () => {
    const store = await readStore();
    const account = activeAccount(store);
    if (!hasTokens(account)) return notSignedIn;
    let outcome = { revoked: false, problem: revoke ? 'no refresh token to revoke' : 'revocation skipped' };
    if (revoke && account.refresh_token) outcome = await revokeRefreshToken(account);
    store.accounts[account.client_id] = withoutTokens(account, 'signed_out');
    await writeStore(store);
    return {
      signedOut: true,
      revoked: outcome.revoked,
      ...(outcome.revoked ? {} : { revokeProblem: outcome.problem }),
      message: outcome.revoked
        ? 'Signed out and revoked the ChatGPT session.'
        : 'Local tokens were removed, but remote revocation was not confirmed. You can disconnect the app in ChatGPT Settings.',
    };
  });
}

// ---------------------------------------------------------------------------
// Status + dry run (read-only)
// ---------------------------------------------------------------------------

/** Read-only summary of the saved session. Never returns tokens, never writes, never uses the network. */
async function status() {
  const store = await readStore();
  const account = activeAccount(store);
  const signedIn = isConnected(account);
  let storeFileMode = null;
  try {
    storeFileMode = ((await stat(STORE_PATH)).mode & 0o777).toString(8);
  } catch {
    // no file yet
  }
  return {
    storePath: STORE_PATH,
    storeFileMode,
    hostId: store?.ext_agent_host_id ?? null,
    signedIn,
    planUsage: signedIn && hasPlanUsage(account),
    accountStatus: account?.status ?? null,
    email: account?.email ?? null,
    name: account?.name ?? null,
    clientId: account?.client_id ?? null,
    scopes: parseScopes(account?.scopes),
    accessTokenExpiresAt: account?.expires_at ?? null,
    accessTokenValid: signedIn && expiresAtMs(account) > Date.now(),
    canRefresh: Boolean(account?.refresh_token),
    savedAt: account?.saved_at ?? null,
    /** UI: show the one-time "You're using your ChatGPT plan" confirmation once per value of this. */
    planUsageFirstEnabledAt: account?.plan_usage_first_enabled_at ?? null,
    otherSavedAccounts: Object.keys(store?.accounts ?? {}).filter((id) => id !== store?.active_client_id).length,
    manageUsageUrl: MANAGE_USAGE_URL,
  };
}

/**
 * Dry run: the authorize URL login() would open. Starts no listener and writes nothing; state, nonce
 * and the PKCE pair are throwaway, and the host ID is ephemeral unless one is already saved.
 */
async function previewAuthorizeUrl({ newAccount = false, reconsent = false, port } = {}) {
  let store = null;
  try {
    store = await readStore();
  } catch {
    store = null;
  }
  const previous = newAccount ? null : activeAccount(store);
  const savedClientId = previous?.client_id && previous.client_id !== DYNAMIC_CLIENT_ID ? previous.client_id : undefined;
  const { authorization_endpoint: authorizationEndpoint } = await endpoints();
  const envPort = process.env.SIWC_PORT ? Number(process.env.SIWC_PORT) : undefined;
  const chosenPort = port ?? envPort ?? DEFAULT_CALLBACK_PORT;
  const hostId = store?.ext_agent_host_id ?? `urn:uuid:${randomUUID()}`;
  const url = buildAuthorizeUrl({
    authorizationEndpoint,
    clientId: savedClientId ?? DYNAMIC_CLIENT_ID,
    redirectUri: `http://127.0.0.1:${chosenPort}${CALLBACK_PATH}`,
    state: randomValue(),
    nonce: randomValue(),
    codeChallenge: pkcePair().challenge,
    hostId,
    loginHint: savedClientId ? previous?.email : undefined,
    reconsent,
  });
  return { url, hostIdPersisted: Boolean(store?.ext_agent_host_id), reauthorization: Boolean(savedClientId) };
}


// ===========================================================================
// OpenAI Responses API client (copied from integrations/openai/llm.mjs)
// ===========================================================================
const siwcStatus = status;
/**
 * complete(): one OpenAI Responses API call using whichever credential is available, in this order:
 *   1. Sign in with ChatGPT: the user's ChatGPT Plus/Pro plan (signed in, plan-usage scope granted)
 *   2. process.env.OPENAI_API_KEY: standard API billing
 *   3. neither: throws NoLLMAvailableError
 * Set OPENAI_AUTH=chatgpt|api_key|auto (default auto) to force a path.
 *
 * Both paths call POST https://api.openai.com/v1/responses with store:false and stream:true, as
 * ChatGPT plan usage requires (https://developers.openai.com/siwc/token-sharing-open-source/preview-limitations).
 * Dependency-free Node ESM.
 */

// Settings such as OPENAI_API_KEY and OPENAI_MODEL can live in <project root>/.env.local (gitignored).
// Variables already set in the environment win.

function loadEnvFile(file) {
  let text;
  try {
    text = readFileSync(file, 'utf8');
  } catch {
    return;
  }
  for (const raw of text.split('\n')) {
    const line = raw.trim();
    const eq = line.indexOf('=');
    if (!line || line.startsWith('#') || eq < 1) continue;
    const key = line.slice(0, eq).trim();
    const value = line.slice(eq + 1).trim().replace(/^(['"])(.*)\1$/, '$2');
    if (value && process.env[key] === undefined) process.env[key] = value;
  }
}

const API_BASE = 'https://api.openai.com/v1';
/** Model used in the SIWC inference docs; also an API model. Override with OPENAI_MODEL or complete({ model }). */
const DEFAULT_MODEL = 'gpt-6.1-sol';
const AUTH_CHATGPT = 'chatgpt';
const AUTH_API_KEY = 'api_key';

const DEFAULT_TIMEOUT_MS = 5 * 60_000;
const MAX_ATTEMPTS = 3;

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

/** Neither a usable ChatGPT sign-in nor OPENAI_API_KEY. `reasons` says why for each path. */
class NoLLMAvailableError extends Error {
  constructor(reasons = []) {
    super(`No OpenAI credentials available. ${reasons.join(' ')}`.trim());
    this.name = 'NoLLMAvailableError';
    this.code = 'no_llm_available';
    this.reasons = reasons;
  }
}

/**
 * The API rejected or failed the request. `kind` is a stable category for UI decisions:
 * usage_limit | not_eligible | temporarily_unavailable | unsupported_capability | unsupported_route |
 * auth | not_authorized | client_not_enabled | policy_or_region | model_not_found | rate_limited |
 * quota | invalid_request | server_error | network | stream_interrupted | request_failed
 */
class LLMRequestError extends Error {
  constructor({ kind, code, status, param, requestId, authPath, retryable = false, hint, serverMessage, phase, retryAfterMs }) {
    const parts = [hint ?? 'The OpenAI request failed.'];
    if (code) parts.push(`[${code}]`);
    if (status) parts.push(`(HTTP ${status})`);
    if (param) parts.push(`param=${param}`);
    super(parts.join(' '));
    this.name = 'LLMRequestError';
    Object.assign(this, { kind, code: code ?? null, status: status ?? null, param: param ?? null, requestId: requestId ?? null });
    Object.assign(this, { authPath, retryable, phase });
    if (serverMessage) this.serverMessage = serverMessage;
    if (retryAfterMs !== undefined) this.retryAfterMs = retryAfterMs;
    if (kind === 'usage_limit') this.manageUsageUrl = MANAGE_USAGE_URL;
  }
}

/** The request completed but the output is unusable: refusal | incomplete | invalid_json | schema_mismatch. */
class LLMOutputError extends Error {
  constructor(code, message, extra = {}) {
    super(message);
    this.name = 'LLMOutputError';
    this.code = code;
    Object.assign(this, extra);
  }
}

// [kind, retryable, hint]. Codes and recovery advice from
// https://developers.openai.com/siwc/token-sharing-open-source/errors-and-recovery
const KNOWN_CODES = {
  subscription_sharing_user_not_eligible: ['not_eligible', false, 'ChatGPT plan usage is not available for this account, workspace or policy (needs an eligible Plus or Pro plan). Use an OpenAI API key instead.'],
  subscription_sharing_usage_limit_exceeded: ['usage_limit', false, `The ChatGPT plan or this app's usage limit was reached. Review usage and limits at ${MANAGE_USAGE_URL}`],
  subscription_sharing_usage_unavailable: ['temporarily_unavailable', true, 'ChatGPT usage could not be checked right now. Try again shortly.'],
  subscription_sharing_user_unavailable: ['temporarily_unavailable', true, 'ChatGPT account information is temporarily unavailable. Try again shortly.'],
  subscription_sharing_unsupported_capability: ['unsupported_capability', false, 'ChatGPT plan usage does not support a parameter, tool or model in this request (see param).'],
  subscription_sharing_route_not_supported: ['unsupported_route', false, 'Only POST /v1/responses is supported with ChatGPT plan usage.'],
  subscription_sharing_invalid_user: ['auth', false, `ChatGPT could not validate the subscriber context. If this persists, sign in again (${CLI} login).`],
  chatpass_v2_scope_not_authorized: ['not_authorized', false, 'The granted ChatGPT permissions do not authorize this request. Check the client and grant.'],
  chatpass_v2_invalid_authorization_context: ['not_authorized', false, 'The ChatGPT authorization context does not permit this request. Check the client and grant.'],
  subscription_sharing_v2_client_not_enabled: ['client_not_enabled', false, 'This app registration is not enabled for ChatGPT plan usage.'],
  model_not_found: ['model_not_found', false, `This model is not available for these credentials. Set OPENAI_MODEL or list models with: ${CLI} models`],
  insufficient_quota: ['quota', false, 'The OpenAI API key has no remaining quota or billing.'],
  credit_balance_exhausted: ['quota', false, 'The OpenAI API account has no credits left. Add credits at https://platform.openai.com/settings/organization/billing/ or use Sign in with ChatGPT.'],
  invalid_api_key: ['auth', false, 'OPENAI_API_KEY was rejected.'],
  rate_limit_exceeded: ['rate_limited', true, 'Rate limited by the OpenAI API.'],
};
// Older spellings seen in the reference SDK; keep the server's exact code on the error.
const LEGACY_CODES = {
  subscription_sharing_v2_user_not_eligible: 'subscription_sharing_user_not_eligible',
  subscription_sharing_v2_route_not_supported: 'subscription_sharing_route_not_supported',
  subscription_sharing_v2_invalid_user: 'subscription_sharing_invalid_user',
  subscription_sharing_v2_user_unavailable: 'subscription_sharing_user_unavailable',
};

const shortText = (value, max = 300) =>
  typeof value === 'string' && value ? (value.length > max ? `${value.slice(0, max)}...` : value) : undefined;

function errorFromBody(body, { status, requestId, authPath, phase, retryAfterMs }) {
  let detail = isObject(body) ? body : {};
  for (let depth = 0; depth < 4; depth += 1) {
    if (isObject(detail.response) && isObject(detail.response.error)) detail = detail.response.error;
    else if (isObject(detail.error)) detail = detail.error;
    else if (isObject(detail.detail)) detail = detail.detail;
    else break;
  }
  const rawCode =
    typeof detail.code === 'string' ? detail.code : typeof detail.error === 'string' ? detail.error : undefined;
  const code = rawCode && /^[A-Za-z0-9_.:-]{1,100}$/.test(rawCode) ? rawCode : undefined;
  // Direct-admission failures can be {"detail": "..."}: diagnostic text, not a machine-readable code.
  const serverMessage = shortText(detail.message) ?? shortText(isObject(body) ? body.detail : undefined) ?? shortText(detail.detail);
  const param = typeof detail.param === 'string' ? detail.param : undefined;
  let [kind, retryable, hint] = KNOWN_CODES[LEGACY_CODES[code] ?? code] ?? [];
  if (!kind) {
    const plan = authPath === AUTH_CHATGPT;
    if (status === 401) [kind, retryable, hint] = ['auth', false, plan ? 'The ChatGPT credential or plan permission was not accepted. Check the signed-in account and granted scopes, or sign in again.' : 'OPENAI_API_KEY was rejected.'];
    else if (status === 403) [kind, retryable, hint] = ['policy_or_region', false, 'A policy or permission check, such as the permitted serving region, prevented this request.'];
    else if (status === 429) [kind, retryable, hint] = plan ? ['rate_limited', false, `Too many requests. Wait before retrying; usage limits: ${MANAGE_USAGE_URL}`] : ['rate_limited', true, 'Rate limited by the OpenAI API.'];
    else if (status === 503) [kind, retryable, hint] = ['temporarily_unavailable', true, plan ? 'ChatGPT plan routing is unavailable or not enabled right now. Try again later.' : 'The OpenAI API is temporarily unavailable.'];
    else if (status >= 500) [kind, retryable, hint] = ['server_error', true, 'OpenAI returned a server error. Try again shortly.'];
    else if (status === 400 || status === 404 || status === 422) [kind, retryable, hint] = ['invalid_request', false, 'OpenAI rejected the request. Check the model, input and parameters.'];
    else [kind, retryable, hint] = ['request_failed', false, 'The OpenAI request failed.'];
  }
  return new LLMRequestError({ kind, code, status, param, requestId, authPath, retryable, hint, serverMessage, phase, retryAfterMs });
}

/** UI helper: { kind, message, action?: { label, url } } for any error thrown by complete(). */
function describeError(error) {
  if (error instanceof NoLLMAvailableError) {
    return { kind: 'no_llm_available', message: error.message, action: { label: 'Continue with ChatGPT', command: `${CLI} login` } };
  }
  if (error instanceof LLMRequestError) {
    const action = error.kind === 'usage_limit' || error.kind === 'rate_limited' ? { label: 'Manage usage', url: MANAGE_USAGE_URL } : undefined;
    return { kind: error.kind, message: error.message, ...(action ? { action } : {}), retryable: error.retryable };
  }
  if (error instanceof LLMOutputError) return { kind: error.code, message: error.message };
  if (error instanceof LoginRequiredError || error instanceof PlanUsageNotGrantedError) {
    return { kind: error.code, message: error.message, action: { label: 'Continue with ChatGPT', command: `${CLI} login` } };
  }
  return { kind: 'error', message: error?.message ?? String(error) };
}

// ---------------------------------------------------------------------------
// Auth selection
// ---------------------------------------------------------------------------

function authMode(value) {
  const mode = String(value ?? process.env.OPENAI_AUTH ?? 'auto').toLowerCase();
  if (!['auto', AUTH_CHATGPT, AUTH_API_KEY].includes(mode)) throw new TypeError(`OPENAI_AUTH must be auto, chatgpt or api_key (got ${mode}).`);
  return mode;
}

/** Internal: returns { path, token }. Never expose the token to a browser or a log. */
async function resolveAuth(preference) {
  const mode = authMode(preference);
  const reasons = [];
  if (mode !== AUTH_API_KEY) {
    try {
      return { path: AUTH_CHATGPT, token: await getAccessToken() };
    } catch (error) {
      const notUsable = error instanceof LoginRequiredError || error instanceof PlanUsageNotGrantedError;
      // A temporary sign-in problem is surfaced instead of silently switching to another billing path.
      if (!notUsable) throw error;
      if (mode === AUTH_CHATGPT) throw new NoLLMAvailableError([`ChatGPT: ${error.message}`, '(OPENAI_AUTH=chatgpt)']);
      reasons.push(`ChatGPT: ${error.message}`);
    }
  }
  if (mode !== AUTH_CHATGPT) {
    const key = process.env.OPENAI_API_KEY?.trim();
    if (key) return { path: AUTH_API_KEY, token: key, note: reasons.join(' ') || undefined };
    reasons.push('API key: OPENAI_API_KEY is not set.');
  }
  throw new NoLLMAvailableError(reasons);
}

/**
 * What complete() would use right now, without network calls or token refreshes. Safe to send to a
 * browser: contains no tokens.
 */
async function describeAuth() {
  const mode = authMode();
  let chatgpt;
  try {
    chatgpt = await siwcStatus();
  } catch (error) {
    chatgpt = { signedIn: false, planUsage: false, error: error.message };
  }
  const apiKeyConfigured = Boolean(process.env.OPENAI_API_KEY?.trim());
  let path = null;
  if (mode !== AUTH_API_KEY && chatgpt.signedIn && chatgpt.planUsage) path = AUTH_CHATGPT;
  else if (mode !== AUTH_CHATGPT && apiKeyConfigured) path = AUTH_API_KEY;
  return {
    path,
    mode,
    apiKeyConfigured,
    model: process.env.OPENAI_MODEL || DEFAULT_MODEL,
    chatgpt: {
      signedIn: chatgpt.signedIn,
      planUsage: chatgpt.planUsage,
      email: chatgpt.email ?? null,
      accountStatus: chatgpt.accountStatus ?? null,
      accessTokenExpiresAt: chatgpt.accessTokenExpiresAt ?? null,
      planUsageFirstEnabledAt: chatgpt.planUsageFirstEnabledAt ?? null,
      ...(chatgpt.error ? { error: chatgpt.error } : {}),
    },
    manageUsageUrl: MANAGE_USAGE_URL,
  };
}

// ---------------------------------------------------------------------------
// Models
// ---------------------------------------------------------------------------

let catalogCache = null;

/**
 * Models for the current credentials, in the server's order. On the ChatGPT path this is the
 * account's own catalog ({ models: [{ slug, display_name, visibility }] }, keeping visibility "list").
 */
async function listModels({ authMode: preference } = {}) {
  return fetchCatalog(await resolveAuth(preference));
}

async function fetchCatalog(auth) {
  if (catalogCache && catalogCache.token === auth.token && Date.now() - catalogCache.at < 10 * 60_000) {
    return catalogCache.models;
  }
  let response;
  try {
    response = await fetch(`${API_BASE}/models`, {
      headers: { authorization: `Bearer ${auth.token}`, accept: 'application/json' },
      signal: AbortSignal.timeout(20_000),
      redirect: 'error',
    });
  } catch (error) {
    throw new LLMRequestError({ kind: 'network', authPath: auth.path, retryable: true, phase: 'admission', hint: `Could not reach api.openai.com (${error?.cause?.code ?? error.name}).` });
  }
  const requestId = response.headers.get('x-request-id') ?? undefined;
  const body = await response.json().catch(() => undefined);
  if (!response.ok) throw errorFromBody(body, { status: response.status, requestId, authPath: auth.path, phase: 'admission' });
  let models = [];
  if (Array.isArray(body?.models)) {
    models = body.models
      .filter((model) => isObject(model) && model.visibility === 'list' && typeof model.slug === 'string' && model.slug)
      .map((model) => ({ slug: model.slug, displayName: typeof model.display_name === 'string' ? model.display_name : model.slug }));
  } else if (Array.isArray(body?.data)) {
    models = body.data
      .filter((model) => isObject(model) && typeof model.id === 'string')
      .map((model) => ({ slug: model.id, displayName: model.id }));
  }
  catalogCache = { token: auth.token, at: Date.now(), models };
  return models;
}

async function chooseModel(auth, requested) {
  if (requested) return requested;
  if (process.env.OPENAI_MODEL) return process.env.OPENAI_MODEL;
  if (auth.path === AUTH_CHATGPT) {
    // Plan usage only works with models available to the signed-in account: keep the default when the
    // account lists it, otherwise take the first listed model (server order). Best effort.
    try {
      const models = await fetchCatalog(auth);
      if (models.length && !models.some((model) => model.slug === DEFAULT_MODEL)) return models[0].slug;
    } catch {
      // fall back to the default
    }
  }
  return DEFAULT_MODEL;
}

// ---------------------------------------------------------------------------
// Responses API streaming
// ---------------------------------------------------------------------------

const STOP = Symbol('stop');

async function readEventStream(body, onEvent) {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let dataLines = [];
  const dispatch = () => {
    if (!dataLines.length) return undefined;
    const data = dataLines.join('\n');
    dataLines = [];
    if (data === '[DONE]') return undefined;
    let event;
    try {
      event = JSON.parse(data);
    } catch {
      throw new LLMRequestError({ kind: 'stream_interrupted', phase: 'stream', hint: 'The response stream contained an invalid event.' });
    }
    return isObject(event) ? onEvent(event) : undefined;
  };
  try {
    for (;;) {
      const { value, done } = await reader.read();
      buffer += decoder.decode(value ?? new Uint8Array(), { stream: !done });
      const lines = buffer.split('\n');
      buffer = done ? '' : lines.pop();
      for (let line of lines) {
        if (line.endsWith('\r')) line = line.slice(0, -1);
        if (line === '') {
          if (dispatch() === STOP) return;
        } else if (line.startsWith('data:')) {
          dataLines.push(line.slice(5).replace(/^ /, ''));
        } // comments (":"), event:, id: and retry: lines are ignored; the type is inside data
      }
      if (done) {
        dispatch();
        return;
      }
    }
  } finally {
    reader.cancel().catch(() => {});
  }
}

function outputFromResponse(response) {
  let text = '';
  let refusal = '';
  for (const item of Array.isArray(response?.output) ? response.output : []) {
    if (item?.type !== 'message' || !Array.isArray(item.content)) continue;
    for (const part of item.content) {
      if (part?.type === 'output_text' && typeof part.text === 'string') text += part.text;
      if (part?.type === 'refusal' && typeof part.refusal === 'string') refusal += part.refusal;
    }
  }
  return { text, refusal };
}

function parseRetryAfter(response) {
  const value = response.headers.get('retry-after');
  if (!value) return undefined;
  const seconds = Number(value);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
  const date = Date.parse(value);
  return Number.isFinite(date) ? Math.max(0, date - Date.now()) : undefined;
}

async function streamResponse(auth, body, { signal, onDelta, timeoutMs }) {
  const timeout = AbortSignal.timeout(timeoutMs);
  const combined = signal ? AbortSignal.any([signal, timeout]) : timeout;
  let response;
  try {
    response = await fetch(`${API_BASE}/responses`, {
      method: 'POST',
      headers: {
        authorization: `Bearer ${auth.token}`,
        'content-type': 'application/json',
        accept: 'text/event-stream',
      },
      body: JSON.stringify(body),
      signal: combined,
      redirect: 'error',
    });
  } catch (error) {
    if (signal?.aborted) throw error;
    throw new LLMRequestError({ kind: 'network', authPath: auth.path, retryable: true, phase: 'admission', hint: `Could not reach api.openai.com (${error?.cause?.code ?? error.name}).` });
  }
  const requestId = response.headers.get('x-request-id') ?? undefined;
  if (!response.ok) {
    const errorBody = await response.json().catch(() => undefined);
    throw errorFromBody(errorBody, { status: response.status, requestId, authPath: auth.path, phase: 'admission', retryAfterMs: parseRetryAfter(response) });
  }
  const contentType = response.headers.get('content-type')?.split(';')[0].trim().toLowerCase();
  // The plan-usage route may omit Content-Type on a valid stream, so only reject a clearly wrong one.
  if (!response.body || (contentType && contentType !== 'text/event-stream')) {
    await response.body?.cancel().catch(() => {});
    throw new LLMRequestError({ kind: 'stream_interrupted', status: response.status, requestId, authPath: auth.path, phase: 'stream', hint: `Expected an event stream but got ${contentType ?? 'no body'}.` });
  }

  const state = { text: '', refusal: '', completed: null, failed: null, incomplete: null, sawDelta: false };
  try {
    await readEventStream(response.body, (event) => {
      switch (event.type) {
        case 'response.output_text.delta':
          if (typeof event.delta === 'string') {
            state.text += event.delta;
            state.sawDelta = true;
            onDelta?.(event.delta);
          }
          return undefined;
        case 'response.refusal.delta':
          if (typeof event.delta === 'string') state.refusal += event.delta;
          return undefined;
        case 'response.completed':
          state.completed = isObject(event.response) ? event.response : {};
          return STOP;
        case 'response.failed':
        case 'error':
          state.failed = event;
          return STOP;
        case 'response.incomplete':
          state.incomplete = isObject(event.response) ? event.response : {};
          return STOP;
        default:
          return undefined;
      }
    });
  } catch (error) {
    if (error instanceof LLMRequestError) throw Object.assign(error, { authPath: auth.path, requestId });
    if (signal?.aborted) throw error;
    throw new LLMRequestError({ kind: 'stream_interrupted', authPath: auth.path, requestId, retryable: false, phase: 'stream', hint: timeout.aborted ? `The response did not finish within ${Math.round(timeoutMs / 1000)}s.` : 'The connection was interrupted before the response completed.' });
  }

  if (state.failed) {
    const error = errorFromBody(state.failed, { requestId, authPath: auth.path, phase: 'stream' });
    error.emittedOutput = state.sawDelta;
    throw error;
  }
  if (state.incomplete) {
    const reason = state.incomplete.incomplete_details?.reason ?? 'unknown';
    throw new LLMOutputError('incomplete', `The response stopped before completing (${reason}).`, { partialText: state.text, authPath: auth.path });
  }
  // Only response.completed counts as success (docs).
  if (!state.completed) {
    throw new LLMRequestError({ kind: 'stream_interrupted', authPath: auth.path, requestId, phase: 'stream', hint: 'The stream ended without response.completed.' });
  }
  const fromOutput = outputFromResponse(state.completed);
  return {
    text: state.text || fromOutput.text,
    refusal: state.refusal || fromOutput.refusal,
    id: state.completed.id ?? null,
    model: state.completed.model ?? body.model,
    usage: state.completed.usage ?? null,
    requestId: requestId ?? null,
  };
}

async function streamWithRetry(auth, body, options) {
  for (let attempt = 1; ; attempt += 1) {
    try {
      return await streamResponse(auth, body, options);
    } catch (error) {
      const retryable =
        error instanceof LLMRequestError &&
        error.retryable &&
        (error.phase === 'admission' || (error.kind === 'temporarily_unavailable' && !error.emittedOutput));
      if (!retryable || attempt >= MAX_ATTEMPTS || options.signal?.aborted) throw error;
      const backoff = error.retryAfterMs ?? 1000 * 3 ** (attempt - 1) + Math.random() * 500; // ~1s, ~3s
      await sleep(Math.min(backoff, 15_000));
    }
  }
}

// ---------------------------------------------------------------------------
// complete()
// ---------------------------------------------------------------------------

function normalizeInput(input) {
  if (typeof input === 'string') return [{ role: 'user', content: input }];
  const list = Array.isArray(input) ? input : isObject(input) ? [input] : null;
  if (!list || !list.length) throw new TypeError('complete(): input must be a non-empty string, message or array of messages.');
  return list.map((message) => {
    if (typeof message === 'string') return { role: 'user', content: message };
    if (!isObject(message)) throw new TypeError('complete(): each input item must be a string or an object.');
    // The plan-usage route rejects system message items; developer messages are the documented alternative.
    return message.role === 'system' ? { ...message, role: 'developer' } : message;
  });
}

const schemaFormatName = (name) => String(name || 'result').replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 64) || 'result';

function jsonOnlyInstruction(schema) {
  return [
    'Respond with a single JSON value only: no Markdown, no code fences, no commentary.',
    'It must validate against this JSON Schema:',
    JSON.stringify(schema),
  ].join('\n');
}

function parseJsonText(text) {
  let candidate = String(text ?? '').trim();
  const fenced = candidate.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fenced) candidate = fenced[1];
  try {
    return JSON.parse(candidate);
  } catch {
    const start = candidate.search(/[[{]/);
    const end = Math.max(candidate.lastIndexOf('}'), candidate.lastIndexOf(']'));
    if (start >= 0 && end > start) {
      try {
        return JSON.parse(candidate.slice(start, end + 1));
      } catch {
        // fall through
      }
    }
  }
  throw new LLMOutputError('invalid_json', 'The model did not return valid JSON.', { text: shortText(text, 2000) });
}

const TYPE_CHECKS = {
  null: (value) => value === null,
  array: Array.isArray,
  object: isObject,
  integer: Number.isInteger,
  number: (value) => typeof value === 'number' && Number.isFinite(value),
  string: (value) => typeof value === 'string',
  boolean: (value) => typeof value === 'boolean',
};

/**
 * Small JSON Schema check (type, enum, const, required, properties, additionalProperties:false,
 * items, anyOf). Used only when structured outputs had to fall back to prompting. No $ref support.
 */
function validateJson(value, schema, at = '$') {
  if (!isObject(schema)) return [];
  if (Array.isArray(schema.anyOf)) {
    return schema.anyOf.some((option) => validateJson(value, option, at).length === 0) ? [] : [`${at}: matches none of anyOf`];
  }
  const problems = [];
  if (schema.const !== undefined && value !== schema.const) problems.push(`${at}: expected ${JSON.stringify(schema.const)}`);
  if (Array.isArray(schema.enum) && !schema.enum.includes(value)) problems.push(`${at}: not one of ${schema.enum.map((v) => JSON.stringify(v)).join(', ')}`);
  const types = schema.type === undefined ? [] : Array.isArray(schema.type) ? schema.type : [schema.type];
  if (types.length && !types.some((type) => TYPE_CHECKS[type]?.(value))) return [...problems, `${at}: expected ${types.join(' | ')}`];
  if (isObject(value)) {
    const properties = isObject(schema.properties) ? schema.properties : {};
    for (const key of Array.isArray(schema.required) ? schema.required : []) {
      if (!(key in value)) problems.push(`${at}.${key}: missing`);
    }
    for (const [key, child] of Object.entries(properties)) {
      if (key in value) problems.push(...validateJson(value[key], child, `${at}.${key}`));
    }
    if (schema.additionalProperties === false) {
      for (const key of Object.keys(value)) if (!(key in properties)) problems.push(`${at}.${key}: unexpected property`);
    }
  }
  if (Array.isArray(value) && isObject(schema.items)) {
    value.forEach((item, index) => problems.push(...validateJson(item, schema.items, `${at}[${index}]`)));
  }
  return problems;
}

/**
 * Run one model call.
 *
 * @param {object}   options
 * @param {string}   [options.instructions]   system-level guidance (sent as Responses `instructions`)
 * @param {string|object|object[]} options.input  user text, or Responses input message(s)
 * @param {object}   [options.schema]         JSON Schema for structured output. Strict mode rules apply:
 *                                            every object needs additionalProperties:false and must list
 *                                            all its properties in `required` (use ["string","null"] for optional)
 * @param {string}   [options.schemaName]     name for the schema (default "result")
 * @param {string}   [options.model]          overrides OPENAI_MODEL and the default
 * @param {string}   [options.reasoningEffort] e.g. "low" | "medium" | "high"; omitted unless set
 * @param {string}   [options.authMode]       "auto" | "chatgpt" | "api_key" (default OPENAI_AUTH or auto)
 * @param {AbortSignal} [options.signal]
 * @param {(delta: string) => void} [options.onDelta]  streamed text deltas
 * @param {number}   [options.timeoutMs]      whole-request timeout (default 5 minutes)
 * @returns {Promise<{ text: string, json?: any, model: string, authPath: 'chatgpt'|'api_key',
 *   structuredMode: null|'json_schema'|'prompted', usage: object|null, responseId: string|null,
 *   requestId: string|null, note?: string }>}
 */
async function complete({
  instructions,
  input,
  schema,
  schemaName = 'result',
  model,
  reasoningEffort,
  authMode: preference,
  signal,
  onDelta,
  timeoutMs = DEFAULT_TIMEOUT_MS,
} = {}) {
  const messages = normalizeInput(input);
  const auth = await resolveAuth(preference);
  const modelId = await chooseModel(auth, model);

  const base = { model: modelId, input: messages, store: false, stream: true };
  if (instructions) base.instructions = instructions;
  if (reasoningEffort) base.reasoning = { effort: reasoningEffort };

  let structuredMode = null;
  let request = base;
  if (schema) {
    structuredMode = 'json_schema';
    request = { ...base, text: { format: { type: 'json_schema', name: schemaFormatName(schemaName), schema, strict: true } } };
  }

  const options = { signal, onDelta, timeoutMs };
  let result;
  try {
    result = await streamWithRetry(auth, request, options);
  } catch (error) {
    // Structured outputs are not listed as supported or unsupported for ChatGPT plan usage. If the
    // route rejects `text`, retry once with the schema in the instructions and validate locally.
    const textRejected =
      schema &&
      error instanceof LLMRequestError &&
      error.code === 'subscription_sharing_unsupported_capability' &&
      (!error.param || /^text/.test(error.param));
    if (!textRejected) throw error;
    structuredMode = 'prompted';
    request = { ...base, instructions: [instructions, jsonOnlyInstruction(schema)].filter(Boolean).join('\n\n') };
    result = await streamWithRetry(auth, request, options);
  }

  if (!result.text && result.refusal) {
    throw new LLMOutputError('refusal', `The model refused: ${shortText(result.refusal)}`, { refusal: result.refusal, authPath: auth.path, model: result.model });
  }

  let json;
  if (schema) {
    json = parseJsonText(result.text);
    if (structuredMode === 'prompted') {
      const problems = validateJson(json, schema);
      if (problems.length) {
        throw new LLMOutputError('schema_mismatch', `The JSON did not match the schema: ${problems.slice(0, 5).join('; ')}`, { json, text: shortText(result.text, 2000) });
      }
    }
  }

  return {
    text: result.text,
    ...(schema ? { json } : {}),
    model: result.model ?? modelId,
    authPath: auth.path,
    structuredMode,
    usage: result.usage,
    responseId: result.id,
    requestId: result.requestId,
    ...(auth.note ? { note: auth.note } : {}),
  };
}

// ===========================================================================
// Phenotech research worker (main loop). The code above this line is a copy of
// integrations/openai/siwc.mjs and llm.mjs, inlined by pipeline/crowd/build_worker.mjs.
// ===========================================================================

const WORKER_VERSION = '2026-10-04';
const ANTHROPIC_DEFAULT_MODEL = 'claude-sonnet-5-5';
const DEFAULT_SERVER = 'https://rare-disease-atlas-five.vercel.app';
const CONFIG_PATH = path.join(WORKER_HOME, 'config.json');
const SHORT = { mechanism: 'mechanism', process: 'process', therapies: 'therapies', phenotypes: 'phenotypes', natural_history: 'natural history', research_groups: 'research groups' };

const HELP = `Phenotech research worker ${WORKER_VERSION}

Researches rare diseases from the atlas research queue with YOUR OpenAI access, in a loop until you stop it.
The atlas fetches the PubMed abstracts; your model extracts claims; the atlas verifies every quote.

Usage:
  node rare-atlas-worker.mjs [--server URL] [options]
  node rare-atlas-worker.mjs login [--reconsent] [--new-account]    sign in with ChatGPT (Plus/Pro) now
  node rare-atlas-worker.mjs status                                 show the ChatGPT sign-in and atlas token
  node rare-atlas-worker.mjs logout                                 sign out of ChatGPT and forget the atlas token

Options:
  --server URL      atlas site (default ${DEFAULT_SERVER})
  --model SLUG      model to use (default: ${DEFAULT_MODEL}, or the first model your ChatGPT plan lists)
  --api-key         use OPENAI_API_KEY (API billing) instead of your ChatGPT plan
  --provider P      openai (default) or anthropic (Claude; reads ANTHROPIC_API_KEY, default model ${ANTHROPIC_DEFAULT_MODEL})
  --max-tasks N     stop after N diseases (default: run until Ctrl-C or the queue is empty)
  --max-calls N     stop after N model calls (a cost cap; the current disease is handed back)
  --help

Atlas worker token: create one on <server>/research-queue while signed in. The worker asks for it once and
keeps it in ${CONFIG_PATH} (mode 600); or set RARE_ATLAS_TOKEN.
ChatGPT credentials are kept in ${path.join(WORKER_HOME, 'secrets')} (mode 600; RARE_ATLAS_SECRETS_DIR overrides).
Ctrl-C once: finish the current model call, hand the disease back with what was found, exit. Twice: exit now.`;

function parseArgv(argv) {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i += 1) {
    const a = argv[i];
    if (!a.startsWith('--')) out._.push(a);
    else if (a.includes('=')) out[a.slice(2, a.indexOf('='))] = a.slice(a.indexOf('=') + 1);
    else if (['server', 'model', 'max-tasks', 'max-calls', 'provider'].includes(a.slice(2))) out[a.slice(2)] = argv[++i];
    else out[a.slice(2)] = true;
  }
  return out;
}

const stamp = () => new Date().toTimeString().slice(0, 8);
const say = (...parts) => console.log(`[${stamp()}]`, ...parts);

async function readConfig() {
  try {
    return JSON.parse(await readFile(CONFIG_PATH, 'utf8'));
  } catch {
    return { tokens: {} };
  }
}
async function writeConfig(config) {
  await mkdir(WORKER_HOME, { recursive: true, mode: 0o700 });
  const tmp = `${CONFIG_PATH}.${process.pid}.tmp`;
  await writeFile(tmp, `${JSON.stringify(config, null, 2)}\n`, { mode: 0o600 });
  await chmod(tmp, 0o600);
  await rename(tmp, CONFIG_PATH);
}

function serverUrl(raw) {
  let u;
  try {
    u = new URL(raw || DEFAULT_SERVER);
  } catch {
    throw new Error(`--server is not a URL: ${raw}`);
  }
  const local = ['127.0.0.1', 'localhost', '[::1]'].includes(u.hostname);
  if (u.protocol !== 'https:' && !(local && u.protocol === 'http:')) throw new Error('--server must use https (http is allowed only for 127.0.0.1/localhost).');
  return u.origin;
}

function ask(question) {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  return new Promise((resolve) => rl.question(question, (answer) => {
    rl.close();
    resolve(answer.trim());
  }));
}

class AtlasError extends Error {
  constructor(message, status) {
    super(message);
    this.status = status;
  }
}

async function atlas(server, token, route, method = 'GET', body) {
  let r;
  try {
    r = await fetch(`${server}${route}`, {
      method,
      headers: { authorization: `Bearer ${token}`, ...(body === undefined ? {} : { 'content-type': 'application/json' }), 'user-agent': `phenotech-worker/${WORKER_VERSION}` },
      body: body === undefined ? undefined : JSON.stringify(body),
      redirect: 'error',
      signal: AbortSignal.timeout(90_000),
    });
  } catch (error) {
    throw new AtlasError(`Could not reach ${server} (${error?.cause?.code ?? error.name}).`, 0);
  }
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw new AtlasError(j.error ?? `${route} returned HTTP ${r.status}`, r.status);
  return j;
}

/** The model's user message for one batch (same text as the browser runner, components/queue/queue-client.ts). */
function batchTexts(p) {
  const d = p.disease;
  const missing = p.checklist.filter((c) => !c.done);
  const head = [
    `Disease: ${d.name}${d.synonyms.length ? ` (also called: ${d.synonyms.join('; ')})` : ''}`,
    `Genes: ${d.genes.join(', ') || 'none recorded'}`,
    `Identifiers: ${[d.mondo, ...d.omim.map((o) => `OMIM:${o}`), ...d.orpha.map((o) => `ORPHA:${o}`)].filter(Boolean).join(', ')}`,
    `Already in the atlas: curated mechanism classes: ${p.known.mechanismClasses.join(', ') || 'none'}; DisMech mechanism chain: ${p.known.dismech ? 'yes' : 'no'}.`,
    missing.length
      ? `Still missing (focus here first): ${missing.map((c) => `${c.label} (have ${c.have} of ${c.need} ${c.unit})`).join('; ')}.`
      : 'The checklist is complete; add any further solid claims.',
    '',
    'Records:',
  ].join('\n');
  const out = [];
  for (let i = 0; i < p.abstracts.length; i += p.batchSize) {
    const recs = p.abstracts.slice(i, i + p.batchSize).map((a) => [
      `PMID: ${a.pmid}`,
      `Title: ${a.title}`,
      `Abstract: ${a.abstract}`,
      `Senior authors: ${a.senior_authors.map((s) => `${s.name} — ${s.affiliation || '(no affiliation listed)'}`).join('; ') || '(none listed)'}`,
    ].join('\n'));
    out.push(`${head}\n\n${recs.join('\n\n')}`);
  }
  return out;
}

const checklistLine = (items) => items.map((c) => `${SHORT[c.id] ?? c.id} ${c.have}/${c.need}${c.done ? ' ok' : ''}`).join(' · ');

async function ensureToken(server, args) {
  if (process.env.RARE_ATLAS_TOKEN) return process.env.RARE_ATLAS_TOKEN.trim();
  const config = await readConfig();
  if (config.tokens?.[server]) return config.tokens[server];
  if (!process.stdin.isTTY) throw new Error(`No atlas worker token. Create one on ${server}/research-queue and set RARE_ATLAS_TOKEN.`);
  console.log(`\nThis worker needs an atlas worker token so your verified claims carry your handle.\nSign in on ${server}/research-queue, click "Create a worker token" and paste it here.`);
  const token = await ask('Worker token: ');
  if (!/^rqw_[A-Za-z0-9_-]{30,80}$/.test(token)) throw new Error('That does not look like a worker token (it starts with rqw_).');
  config.tokens = { ...(config.tokens ?? {}), [server]: token };
  if (!args['no-save']) await writeConfig(config);
  return token;
}

async function forgetToken(server) {
  const config = await readConfig();
  if (config.tokens?.[server]) {
    delete config.tokens[server];
    await writeConfig(config);
  }
}

/** One Anthropic Messages call; strict JSON through a forced tool call whose input_schema is the claim schema. */
async function completeAnthropic({ instructions, input, schema, model, signal }) {
  let r;
  try {
    r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': process.env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: model || ANTHROPIC_DEFAULT_MODEL,
        max_tokens: 8000,
        system: instructions,
        tools: [{ name: 'submit_claims', description: 'Submit the extracted claims and research groups.', input_schema: schema }],
        tool_choice: { type: 'tool', name: 'submit_claims' },
        messages: [{ role: 'user', content: input }],
      }),
      signal: signal ? AbortSignal.any([signal, AbortSignal.timeout(DEFAULT_TIMEOUT_MS)]) : AbortSignal.timeout(DEFAULT_TIMEOUT_MS),
      redirect: 'error',
    });
  } catch (error) {
    if (signal?.aborted) throw error;
    throw Object.assign(new Error(`Could not reach api.anthropic.com (${error?.cause?.code ?? error.name}).`), { kind: 'network' });
  }
  const j = await r.json().catch(() => ({}));
  if (!r.ok) {
    const kind = r.status === 401 ? 'auth' : r.status === 429 ? 'rate_limited' : r.status === 404 ? 'model_not_found' : r.status >= 500 ? 'server_error' : 'invalid_request';
    throw Object.assign(new Error(`Anthropic: ${j.error?.message ?? `HTTP ${r.status}`}`), { kind });
  }
  const call = (j.content ?? []).find((c) => c.type === 'tool_use' && c.name === 'submit_claims');
  if (!call?.input) throw Object.assign(new Error(`Anthropic returned no tool call (stop reason ${j.stop_reason}).`), { kind: 'invalid_json' });
  return { json: call.input, model: j.model ?? model, usage: j.usage ?? null };
}

async function ensureOpenAI(args) {
  if (args.provider === 'anthropic') {
    if (!process.env.ANTHROPIC_API_KEY) throw new Error('--provider anthropic needs ANTHROPIC_API_KEY in the environment.');
    say(`Using Anthropic Claude (${args.model || ANTHROPIC_DEFAULT_MODEL}) with ANTHROPIC_API_KEY (your API credits).`);
    return;
  }
  if (args.provider && args.provider !== 'openai') throw new Error('--provider must be openai or anthropic.');
  if (args['api-key']) {
    if (!process.env.OPENAI_API_KEY) throw new Error('--api-key needs OPENAI_API_KEY in the environment.');
    process.env.OPENAI_AUTH = AUTH_API_KEY;
    say('Using OPENAI_API_KEY (API billing).');
    return;
  }
  process.env.OPENAI_AUTH = AUTH_CHATGPT;
  const st = await status();
  if (st.signedIn && st.planUsage) {
    say(`Using your ChatGPT plan${st.email ? ` (${st.email})` : ''}. Usage and limits: ${MANAGE_USAGE_URL}`);
    return;
  }
  say('Signing in with ChatGPT. A browser window opens; approve "use your ChatGPT plan". The callback is a 127.0.0.1 page on this machine.');
  const result = await login({
    reconsent: Boolean(st.signedIn && !st.planUsage),
    onAuthorizeUrl: (url) => console.log(`If no browser opens, visit:\n${url}\n`),
    onBrowserError: () => console.log('Could not open a browser automatically; use the link above.'),
  });
  if (!result.planUsage) throw new Error('ChatGPT plan usage was not granted, so the worker cannot use your plan. Run again with: node rare-atlas-worker.mjs login --reconsent');
  say(`Signed in${result.email ? ` as ${result.email}` : ''}.`);
}

async function runTask(server, token, packet, model, control, provider) {
  const batches = batchTexts(packet);
  say(`Researching ${packet.disease.name} (${packet.disease.id}; ${packet.disease.genes.join(', ')}), round ${packet.lease.round}/${packet.lease.maxRounds}, ${packet.abstracts.length} abstracts, lease until ${new Date(packet.lease.expiresAt).toLocaleTimeString()}`);
  say(`  checklist: ${checklistLine(packet.checklist)}`);
  const totals = { accepted: 0, rejected: 0 };
  for (let i = 0; i < batches.length; i += 1) {
    if (control.stop) break;
    if (control.calls >= control.maxCalls) {
      say(`  reached --max-calls ${control.maxCalls}; handing the disease back.`);
      control.stop = true;
      break;
    }
    control.calls += 1;
    const started = Date.now();
    let out;
    try {
      const call = provider === 'anthropic' ? completeAnthropic : complete;
      out = await call({ instructions: packet.instructions, input: batches[i], schema: packet.schema, schemaName: 'claims', model, signal: control.abort.signal });
    } catch (error) {
      if (control.stop) break;
      throw error;
    }
    const res = await atlas(server, token, '/api/queue/submit', 'POST', {
      token: packet.lease.token,
      provider,
      model: out.model,
      claims: out.json?.claims ?? [],
      research_groups: out.json?.research_groups ?? [],
    });
    totals.accepted += res.accepted + res.acceptedGroups;
    totals.rejected += res.rejected.length;
    say(`  batch ${i + 1}/${batches.length} (${out.model}, ${((Date.now() - started) / 1000).toFixed(0)}s): ${res.accepted} claims + ${res.acceptedGroups} groups verified, ${res.rejected.length} rejected${res.duplicates ? `, ${res.duplicates} duplicates` : ''}`);
    for (const r of res.rejected.slice(0, 3)) say(`    rejected ${r.kind} #${r.index + 1}: ${r.reason}`);
    say(`  checklist: ${checklistLine(res.checklist)}`);
  }
  const done = await atlas(server, token, '/api/queue/done', 'POST', { token: packet.lease.token });
  const gaps = done.missing.map((m) => SHORT[m] ?? m).join(', ');
  say(done.status === 'complete'
    ? `Done: ${packet.disease.name} is complete and leaves the queue.`
    : done.status === 'retired'
      ? `Handed back: ${packet.disease.name} leaves the queue after ${done.rounds} rounds, still missing ${gaps}.`
      : `Handed back: ${packet.disease.name} returns to the top of the queue; still missing ${gaps}.`);
  return totals;
}

async function main() {
  const args = parseArgv(process.argv.slice(2));
  if (args.help || args.h) {
    console.log(HELP);
    return;
  }
  const command = args._[0];
  const server = serverUrl(args.server);
  if (command === 'login') {
    const r = await login({ reconsent: Boolean(args.reconsent), newAccount: Boolean(args['new-account']), onAuthorizeUrl: (url) => console.log(`If no browser opens, visit:\n${url}\n`), onBrowserError: () => {} });
    console.log(`Signed in${r.email ? ` as ${r.email}` : ''}; plan usage ${r.planUsage ? 'granted' : 'NOT granted (run login --reconsent)'}.`);
    return;
  }
  if (command === 'logout') {
    console.log((await logout()).message);
    await forgetToken(server);
    console.log(`Forgot the atlas token for ${server}.`);
    return;
  }
  if (command === 'status') {
    const st = await status();
    const config = await readConfig();
    console.log(`ChatGPT: ${st.signedIn ? `signed in${st.email ? ` as ${st.email}` : ''}, plan usage ${st.planUsage ? 'granted' : 'not granted'}` : 'not signed in'}`);
    console.log(`Atlas token for ${server}: ${process.env.RARE_ATLAS_TOKEN || config.tokens?.[server] ? 'present' : 'none'}`);
    return;
  }
  if (command) throw new Error(`Unknown command "${command}". Try --help.`);

  console.log(`Phenotech research worker ${WORKER_VERSION} -> ${server}`);
  const token = await ensureToken(server, args);
  await ensureOpenAI(args);
  const maxTasks = args['max-tasks'] ? Math.max(1, Number(args['max-tasks'])) : Infinity;
  const model = typeof args.model === 'string' ? args.model : undefined;

  const maxCalls = args['max-calls'] ? Math.max(1, Number(args['max-calls'])) : Infinity;
  const control = { stop: false, abort: new AbortController(), interrupts: 0, calls: 0, maxCalls };
  process.on('SIGINT', () => {
    control.interrupts += 1;
    if (control.interrupts > 1) {
      console.log('\nExiting now. Your lease expires on its own and the disease returns to the queue.');
      process.exit(130);
    }
    control.stop = true;
    console.log('\nStopping: handing the current disease back (Ctrl-C again to exit immediately)…');
    control.abort.abort();
  });

  const session = { tasks: 0, accepted: 0, rejected: 0 };
  while (!control.stop && session.tasks < maxTasks) {
    let claim;
    try {
      claim = await atlas(server, token, '/api/queue/claim', 'POST', {});
    } catch (error) {
      if (error.status === 401) {
        await forgetToken(server);
        throw new Error(`${error.message} (the saved token was removed; run again to paste a new one).`);
      }
      if (error.status === 429 || error.status === 503 || error.status === 0) {
        say(`${error.message} Waiting 60 s…`);
        await sleep(60_000);
        continue;
      }
      throw error;
    }
    if (!claim.packet) {
      say(claim.message ?? 'The queue is empty. Thank you!');
      break;
    }
    try {
      const t = await runTask(server, token, claim.packet, model, control, args.provider === 'anthropic' ? 'anthropic' : 'openai');
      session.tasks += 1;
      session.accepted += t.accepted;
      session.rejected += t.rejected;
      say(`Session: ${session.tasks} disease(s), ${session.accepted} verified, ${session.rejected} rejected.`);
    } catch (error) {
      const info = error?.kind && !(error instanceof LLMRequestError) ? { kind: error.kind, message: error.message } : describeError(error);
      say(`Stopped: ${info.message}`);
      if (info.action?.url) say(`  ${info.action.label}: ${info.action.url}`);
      try {
        await atlas(server, token, '/api/queue/done', 'POST', { token: claim.packet.lease.token });
        say('  The disease was handed back with what was found so far.');
      } catch {
        // the lease expires on its own
      }
      const fatal = ['usage_limit', 'not_eligible', 'auth', 'not_authorized', 'client_not_enabled', 'quota', 'model_not_found', 'no_llm_available', 'login_required', 'plan_usage_not_granted'];
      if (fatal.includes(info.kind) || error instanceof AtlasError) process.exitCode = 1;
      if (fatal.includes(info.kind) || error instanceof AtlasError || control.stop) break;
      await sleep(5_000);
    }
  }
  say(`Bye. ${session.tasks} disease(s), ${session.accepted} verified claims this session.`);
}

main().catch((error) => {
  console.error(`Error: ${error?.message ?? error}`);
  process.exit(1);
});
